using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEngine.AI;using UnityEditor;using UnityEditor.SceneManagement;
namespace DeliveryService.Mok.Editor {public static class VenueRoadInterceptionBuilder {
 public static void Evening(){var cycle=UnityEngine.Object.FindFirstObjectByType<DayNightCycle>();if(!cycle||EditorApplication.isPlaying)throw new Exception("Edit mode required");EditorSceneManager.SaveScene(cycle.gameObject.scene,"Logs/City-before-evening-fill-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity",true);var fill=cycle.GetComponent<CityEveningVisibility>();if(!fill)fill=cycle.gameObject.AddComponent<CityEveningVisibility>();fill.cycle=cycle;EditorUtility.SetDirty(fill);EditorSceneManager.MarkSceneDirty(cycle.gameObject.scene);EditorSceneManager.SaveScene(cycle.gameObject.scene);File.WriteAllText("Logs/City-evening-fill.txt","Saved subtle evening ambient fill 0.09 / 0.115 / 0.15; fades in 17:00-18:00. Daytime unchanged.");}
 public static void Apply(){var m=UnityEngine.Object.FindFirstObjectByType<VenueFinale>();if(!m||EditorApplication.isPlaying)throw new Exception("Edit mode required");EditorSceneManager.SaveScene(m.gameObject.scene,"Logs/Venue-before-road-guards-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity",true);var d=m.getaway;
 if(d.pursuit){UnityEngine.Object.DestroyImmediate(d.pursuit.gameObject);d.pursuit=null;}if(d.interception)UnityEngine.Object.DestroyImmediate(d.interception.gameObject);
 var root=new GameObject("Getaway roadside guards");root.transform.SetParent(m.transform,false);var control=root.AddComponent<VenueRoadInterception>();control.drive=d;d.interception=control;control.guardGun=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Synty/PolygonHeist/Prefab/Weapons/SM_Wep_RifleBandit_01.prefab");control.rifleShot=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Scripts/Mok/Prologue/Art/CombatFeedback/Rifle shot.wav");control.metalHit=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Scripts/Mok/Prologue/Art/CombatFeedback/Car metal hit.wav");
 var waves=new List<VenueRoadInterception.Wave>();Vector3 previous=d.transform.position;float accumulated=0;
 foreach(var point in d.route){var delta=point.position-previous;float length=delta.magnitude;accumulated+=length;if(length>12&&accumulated>45){var center=previous+delta*.65f;var side=Vector3.Cross(Vector3.up,delta.normalized);var starts=new List<Transform>();
 for(int k=0;k<3;k++){var position=center+side*(k%2==0?5:-5)+delta.normalized*(k-1)*2;if(!NavMesh.SamplePosition(position,out var hit,6,NavMesh.AllAreas))continue;var path=new NavMeshPath();if(!NavMesh.CalculatePath(hit.position,center,NavMesh.AllAreas,path)||path.status!=NavMeshPathStatus.PathComplete)continue;var t=new GameObject("Guard start "+k).transform;t.SetParent(root.transform);t.position=hit.position;starts.Add(t);}
 if(starts.Count>0){var target=new GameObject("Roadblock "+(waves.Count+1)).transform;target.SetParent(root.transform);target.position=center;waves.Add(new VenueRoadInterception.Wave{center=target,starts=starts.ToArray()});accumulated=0;}}
 previous=point.position;}
 if(waves.Count<2)throw new Exception("Insufficient connected guard waves: "+waves.Count);control.waves=waves.ToArray();EditorUtility.SetDirty(d);EditorUtility.SetDirty(control);EditorSceneManager.MarkSceneDirty(m.gameObject.scene);EditorSceneManager.SaveScene(m.gameObject.scene);File.WriteAllText("Logs/Venue-road-guards-install.txt","Saved "+waves.Count+" roadside guard waves; chase cars removed.");
 }
